def _parse_mapping_schema(schema: Mapping[str, Any], value: object) -> dict[str, Any]:
    """Parse and validate output against the complete caller JSON Schema mapping."""
    parsed = _parse_json_object(value)
    shallow: dict[str, Any] = {"type": "object"}
    if "required" in schema:
        shallow["required"] = schema["required"]
    properties = schema.get("properties")
    if isinstance(properties, Mapping):
        shallow["properties"] = {
            name: {"type": prop["type"]} if isinstance(prop, Mapping) and "type" in prop else {}
            for name, prop in properties.items()
        }
    Draft202012Validator(shallow).validate(parsed)
    return parsed

def _parse_mapping_schema(schema: Mapping[str, Any], value: object) -> dict[str, Any]:
    """Parse and validate output against the complete caller JSON Schema mapping."""
    parsed = _parse_json_object(value)
    relaxed = {
        key: item
        for key, item in dict(schema).items()
        if key not in {"additionalProperties", "$defs", "definitions", "allOf", "anyOf", "oneOf", "not"}
    }
    Draft202012Validator(relaxed).validate(parsed)
    return parsed
